referenceFixTemplate:
#include <iostream>
#include <string>
#include <vector>
using namespace std;

struct Box {
    string goods;
    Box(string g) : goods(g) {}
    Box(const Box& other) : goods(other.goods) { cout << "拷贝一份" << endl; }
    Box(Box&& other) : goods(move(other.goods)) { cout << "搬走" << endl; }
};

int main() {
    vector<Box> basket;
    Box a("{goods}");
    basket.push_back(move(a));
    cout << basket[0].goods << endl;
    return 0;
}
